#!/usr/bin/env node
// Reads the tool payload from stdin; exit 2 BLOCKS the command.
const DENY = [/\brm\s+-rf\s+\//, /git\s+push.*--force/, /drop\s+database/i];
let raw = "";
process.stdin.on("data", c => (raw += c));
process.stdin.on("end", () => {
  let cmd = "";
  try { cmd = (JSON.parse(raw).tool_input || {}).command || ""; }
  catch { process.exit(0); }
  const hit = DENY.find(re => re.test(cmd));
  if (hit) {
    console.error("BLOCKED by policy: matched " + hit);
    process.exit(2);          // <-- blocks the tool call, tells Claude why
  }
  process.exit(0);            // allow
});

